&lt;h2 class=&quot;separator&quot;&gt;R&#232;gles de l&#39;intrigue&lt;a class=&quot;headeranchor&quot; id=&quot;R&#232;gles_de_lintrigue_0&quot; href=&quot;#R&#232;gles_de_lintrigue_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;boutonMa&#238;trise&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;Ma&#238;trise&#39;);&quot; onmouseout=&quot;outButton(&#39;Ma&#238;trise&#39;);&quot; onclick=&quot;expandMenu(&#39;Ma&#238;trise&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;triser-Lintrigue.html&quot; title=&quot;Ma&#238;triser l&amp;#39;intrigue&quot;&gt;Ma&#238;triser l&#39;intrigue&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;Ma&#238;trise&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Influence.html&quot; title=&quot;L&amp;#39;influence&quot;&gt;L&#39;influence&lt;/a&gt;&lt;/li&gt;
            &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Influence-Individuelle.html&quot; title=&quot;L&amp;#39;influence individuelle&quot;&gt;L&#39;influence individuelle&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Influence-Organisationnelle.html&quot; title=&quot;L&amp;#39;influence organisationnelle&quot;&gt;L&#39;influence organisationnelle&lt;/a&gt;&lt;/li&gt;
            &lt;/ul&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casses.html&quot; title=&quot;Les casses&quot;&gt;Les casses&lt;/a&gt;&lt;/li&gt;
            &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casses,-Infiltration.html&quot; title=&quot;L&amp;#39;infiltration (Casses)&quot;&gt;L&#39;infiltration&lt;/a&gt;&lt;/li&gt;
            &lt;/ul&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Prestige-Ui.html&quot; title=&quot;Le prestige&quot;&gt;Le prestige&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;m&#233;sis-Ui.html&quot; title=&quot;Les n&#233;m&#233;sis&quot;&gt;Les n&#233;m&#233;sis&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poursuites.html&quot; title=&quot;Les poursuites&quot;&gt;Les poursuites&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Recherches.html&quot; title=&quot;Les recherches&quot;&gt;Les recherches&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Dintrigue.html&quot; title=&quot;Les sorts d&amp;#39;intrigue&quot;&gt;Les sorts d&#39;intrigue&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Conflits-Sociaux.html&quot; title=&quot;Les conflits sociaux&quot;&gt;Conflits sociaux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Duels-Verbaux.html&quot; title=&quot;Les duels verbaux&quot;&gt;Duels verbaux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-En-Conflit.html&quot; title=&quot;Les comp&#233;tences en conflit&quot;&gt;Comp&#233;tences en conflit&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Modificateurs_de_Prestige_6&quot;&gt;Modificateurs de Prestige&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Valeur_de_Prestige_&#233;lev&#233;e_et_suivants_7&quot;&gt;Valeur de Prestige &#233;lev&#233;e et suivants&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#All&#233;geances_et_don_Prestige_8&quot;&gt;All&#233;geances et don Prestige&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Le_r&#244;le_des_compagnons_darmes_et_des_suivants_9&quot;&gt;Le r&#244;le des compagnons d&#39;armes et des suivants&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Alli&#233;s_monstrueux_10&quot;&gt;Alli&#233;s monstrueux&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Variante_de_Prestige_11&quot;&gt;Variante de Prestige&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Palefrenier_0&quot;&gt;Palefrenier&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Porteur_de_lumi&#232;re_1&quot;&gt;Porteur de lumi&#232;re&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Page_2&quot;&gt;Page&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Recrues_3&quot;&gt;Recrues&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Prestige_inf&#226;me_4&quot;&gt;Prestige inf&#226;me&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Porteur_darme_5&quot;&gt;Porteur d&#39;arme&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;Les interactions sociales et les liens entre les personnes font partie des &#233;l&#233;ments les plus importants de toute histoire. L&#39;une des meilleures fa&#231;ons de d&#233;peindre ces liens et de donner vie &#224; une troupe de PNJ est l&#39;exploit du prestige, m&#234;me si en tirer le meilleur parti peut parfois &#234;tre un d&#233;fi pour les joueurs et les MJ. Cette section offre une relecture approfondie du don &lt;a class=&quot;pagelink&quot; href=&quot;Prestige.html&quot; title=&quot;Prestige&quot;&gt;Prestige&lt;/a&gt;, en pr&#233;sentant des suggestions sur la fa&#231;on d&#39;inclure les compagnons d&#39;arme et les suivants dans votre jeu et de les incorporer dans divers syst&#232;mes de r&#232;gles trouv&#233;s dans le &lt;i&gt;Guide de campagne&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MODIFICATEURS&quot; href=&quot;#MODIFICATEURS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Modificateurs de Prestige&lt;a class=&quot;headeranchor&quot; id=&quot;Modificateurs_de_Prestige_6&quot; href=&quot;#Modificateurs_de_Prestige_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les modificateurs de Prestige figurant dans la description du don &lt;a class=&quot;pagelink&quot; href=&quot;Prestige.html&quot; title=&quot;Prestige&quot;&gt;Prestige&lt;/a&gt; sont concis, si bien que certains MJ appr&#233;cieront d&#39;avoir plus de conseils pour les arbitrer. Avec le syst&#232;me de &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;putation-Et-Renomm&#233;e.html&quot; title=&quot;R&#233;putation et renomm&#233;e&quot;&gt;r&#233;putation et renomm&#233;e&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt;, ou le nouveau syst&#232;me d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Influence.html&quot; title=&quot;L&amp;#39;influence&quot;&gt;influence&lt;/a&gt;, il est possible de cr&#233;er un cadre plus d&#233;taill&#233; pour d&#233;terminer quand ces modificateurs s&#39;appliquent.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Grande renomm&#233;e.&lt;/b&gt; Si vous utilisez le syst&#232;me de &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;putation-Et-Renomm&#233;e.html&quot; title=&quot;R&#233;putation et renomm&#233;e&quot;&gt;r&#233;putation et renomm&#233;e&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt;, un personnage gagne un bonus de +1 &#224; sa valeur de Prestige s&#39;il a une renomm&#233;e d&#39;au moins 30 et un bonus de +2 si elle est d&#39;au moins 55. Autrement, si vous utilisez le syst&#232;me d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Influence-Organisationnelle.html&quot; title=&quot;L&amp;#39;influence organisationnelle&quot;&gt;influence organisationnelle&lt;/a&gt; et que vous recrutez des compagnons d&#39;arme ou des suivants depuis une organisation, un personnage gagne un bonus de +1 &#224; sa valeur de Prestige pour ces compagnons d&#39;arme et ses suivants s&#39;il est de rang 2 ou 3 avec cette organisation et un bonus de +2 s&#39;il est de rang 4.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;G&#233;n&#233;rosit&#233; et avarice.&lt;/b&gt; Pour b&#233;n&#233;ficier d&#39;un bonus de +1 li&#233; &#224; la justice et &#224; la g&#233;n&#233;rosit&#233;, un personnage doit fournir une r&#233;mun&#233;ration sup&#233;rieure &#224; la moyenne &#224; son compagnon d&#39;armes et &#224; ses suivants. Dans le cas d&#39;un compagnon d&#39;armes aventurier, une r&#233;mun&#233;ration moyenne correspond &#224; une part &#233;gale ou l&#233;g&#232;rement inf&#233;rieure &#224; une part &#233;gale du tr&#233;sor. Si un leader offre &#224; son compagnon d&#39;armes et &#224; ses suivant une mauvaise r&#233;mun&#233;ration, il conserve la loyaut&#233; de son compagnon d&#39;armes et de ses suivants, mais subit un malus de -1 &#224; sa valeur de Prestige. S&#39;il ne les paie pas assez pour subsister (ou ne leur fournit pas de quoi vivre), il subit un malus de -2 et risque le double, voire le triple de ce malus si ce comportement dure plus d&#39;une semaine.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pouvoirs sp&#233;ciaux.&lt;/b&gt; Cela fait r&#233;f&#233;rence &#224; quelque chose qui va au-del&#224; de la puissance typique qu&#39;un personnage acquiert en gagnant des niveaux (ce qui est d&#233;j&#224; refl&#233;t&#233; dans sa valeur de Prestige par l&#39;inclusion du niveau de personnage). Un personnage mythique gagnerait certainement le bonus de +1 &#224; sa valeur de Prestige, tout comme celui qui poss&#232;de un &lt;a class=&quot;pagelink&quot; href=&quot;Artefacts.html&quot; title=&quot;Les artefacts&quot;&gt;artefact&lt;/a&gt; ou conna&#238;t un certain nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Rituels-Occultes.html&quot; title=&quot;Les rituels occultes&quot;&gt;rituels occultes&lt;/a&gt; puissants et rares.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#233;ussites et &#233;checs.&lt;/b&gt; Un personnage qui obtient une s&#233;rie significative de r&#233;ussites gagne un bonus de +1 &#224; sa valeur de Prestige, et un personnage qui rencontre une s&#233;rie significative d&#39;&#233;checs subit un malus de -1 &#224; sa valeur de Prestige. Si vous utilisez des &lt;a class=&quot;pagelink&quot; href=&quot;Conflits-Sociaux.html&quot; title=&quot;Les conflits sociaux&quot;&gt;conflits sociaux&lt;/a&gt;, un personnage qui gagne un conflit social important &#224; long terme peut gagner un bonus permanent de +1 &#224; sa valeur de Prestige &#224; chaque fois qu&#39;il le fait, et un personnage qui perd un tel conflit peut au contraire subir un malus permanent de -1 &#224; sa valeur de Prestige.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Distance et camaraderie.&lt;/b&gt; Un personnage distant et &#233;litiste subit un malus de -1 &#224; sa valeur de Prestige, alors qu&#39;un personnage amical, solidaire et accessible gagne un bonus de +1 &#224; sa valeur de Prestige. Si vous utilisez le syst&#232;me de &lt;a class=&quot;pagelink&quot; href=&quot;Relations.html&quot; title=&quot;Les relations&quot;&gt;relations&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt;, un personnage gagne &#224; la place un bonus de +1 gr&#226;ce &#224; son amiti&#233; avec un compagnon d&#39;armes si leur niveau de relation atteint la Camaraderie, qui passe &#224; +2 si leur niveau de relation atteint la D&#233;votion ; ce bonus ne se cumule pas avec les modificateurs subis pour la distance ou la camaraderie envers d&#39;autres personnages.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Cruaut&#233;.&lt;/b&gt; Un personnage qui se montre cruel et insensible envers ses compagnons d&#39;armes et ses suivants subit un malus de -2 &#224; sa valeur de Prestige. Dans le cas d&#39;un personnage particuli&#232;rement mal&#233;fique dont la cruaut&#233; fait partie de sa l&#233;gende et qui recrute des individus tout aussi horribles, ce malus peut ne pas s&#39;appliquer, mais il peut subir un malus similaire si elle accomplit trop d&#39;actes de gentillesse, ruinant ainsi sa r&#233;putation cruelle. Cela ne veut pas dire que la plupart des leaders mal&#233;fiques fonctionnent de cette fa&#231;on, cependant, car la gentillesse peut &#234;tre un outil exceptionnellement utile pour un leader manipulateur.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Autres modificateurs du &lt;i&gt;Manuel des joueurs&lt;/i&gt;.&lt;/b&gt; Les autres modificateurs du &lt;i&gt;Manuel des joueurs&lt;/i&gt;, comme le fait d&#39;avoir un familier, de recruter un compagnon d&#39;armes d&#39;un alignement diff&#233;rent ou de causer des morts, sont plus simples &#224; d&#233;terminer. De nombreux personnages peuvent b&#233;n&#233;ficier d&#39;une maison de guilde ou d&#39;une base d&#39;op&#233;rations, obtenant un bonus de +2 &#224; leurs valeurs de Prestige, sp&#233;cifiquement pour les suivants.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Valeur de Prestige &#233;lev&#233;e et suivants&lt;a class=&quot;headeranchor&quot; id=&quot;Valeur_de_Prestige_&#233;lev&#233;e_et_suivants_7&quot; href=&quot;#Valeur_de_Prestige_&#233;lev&#233;e_et_suivants_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Certains personnages peuvent avoir une valeur de Prestige bien sup&#233;rieure &#224; 25, et un MJ peut permettre &#224; ces personnages d&#39;avoir plus de suivants. Pour chaque tranche de 2 points de Prestige au-del&#224; de 25 d&#39;un personnage, multipliez le nombre de suivants de niveau 1 par 1,5 (arrondir &#224; l&#39;inf&#233;rieur) ; le personnage gagne un dixi&#232;me de ce montant en suivants de niveau 2 (arrondir &#224; l&#39;inf&#233;rieur), la moiti&#233; du nombre de suivants de niveau 2 suppl&#233;mentaires en suivants de niveau 3 (arrondir au sup&#233;rieur), la moiti&#233; du nombre de suivants de niveau 3 suppl&#233;mentaires en suivants de niveau 4 (arrondir &#224; l&#39;sup&#233;rieur), et ainsi de suite jusqu&#39;aux adeptes de niveau 6. Pour calculer le nombre de suivants de niveau 1 obtenus &#224; une valeur de Prestige paire sup&#233;rieure &#224; 25, prenez la moyenne du nombre de suivants de niveau 1 obtenus pour les deux valeurs de Prestige impaires les plus proches, et arrondissez &#224; l&#39;inf&#233;rieur. Ensuite, calculez le nombre de suivants restants de la m&#234;me mani&#232;re que pour les valeurs impaires de Prestige (avec une exception : un personnage avec une valeur de Prestige de 26 a deux suivants de niveau 6).&lt;br /&gt;&lt;br /&gt;Par exemple, un personnage avec une valeur de Prestige de 27 aura 202 suivants de niveau 1, 20 de niveau 2, 10 de niveau 3, 5 de niveau 4, 3 de niveau 5 et 2 de niveau 6. En revanche, un personnage avec une valeur de Prestige de 26 aura 168 suivants de niveau 1, 16 de niveau 2, 8 de niveau 3, 4 de niveau 4, 2 de niveau 5 et 2 de niveau 6 (en raison de l&#39;exception).&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;All&#233;geances et don Prestige&lt;a class=&quot;headeranchor&quot; id=&quot;All&#233;geances_et_don_Prestige_8&quot; href=&quot;#All&#233;geances_et_don_Prestige_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les all&#233;geances contradictoires et les trahisons potentielles font partie de l&#39;excitation du don &lt;a class=&quot;pagelink&quot; href=&quot;Prestige.html&quot; title=&quot;Prestige&quot;&gt;Prestige&lt;/a&gt;. Avoir des suivants totalement loyaux affaiblit la tension du jeu - imaginez si tous les PJs et PNJs utilisaient Prestige pour s&#39;entourer d&#39;alli&#233;s implacablement loyaux qu&#39;aucun camp ne peut subvertir, tromper ou recruter. Les compagnons d&#39;armes et les suivants commencent par &#234;tre v&#233;ritablement loyaux envers leurs chefs, mais ils ne sont pas &#224; l&#39;abri de la corruption, du chantage, du remplacement par un imposteur et d&#39;autres formes de menaces et d&#39;incitations.&lt;br /&gt;&lt;br /&gt;D&#39;un autre c&#244;t&#233;, les joueurs aiment recevoir un avantage plus concret de leurs dons - les avantages de &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt;, par exemple, ne peuvent pas &#234;tre r&#233;duits par des pots-de-vin ou des chicaneries. Pour cette raison, ainsi que pour &#233;quilibrer les projecteurs, envisagez de rendre le don &lt;a class=&quot;pagelink&quot; href=&quot;Prestige.html&quot; title=&quot;Prestige&quot;&gt;Prestige&lt;/a&gt; gratuit dans une campagne ax&#233;e sur l&#39;intrigue, avec la mise en garde que les compagnons d&#39;armes des joueurs peuvent changer d&#39;all&#233;geance dans certaines circonstances. Parfois, un petit avertissement est tout ce qu&#39;il faut pour &#233;viter un choc d&#233;sagr&#233;able des attentes plus tard dans la partie.&lt;br /&gt;&lt;br /&gt;Certains groupes demandent aux joueurs poss&#233;dant le don &lt;a class=&quot;pagelink&quot; href=&quot;Prestige.html&quot; title=&quot;Prestige&quot;&gt;Prestige&lt;/a&gt; de diriger leurs compagnons d&#39;armes pendant le combat afin de d&#233;charger le MJ de la gestion de PNJ suppl&#233;mentaires. Cette m&#233;thode peut toujours &#234;tre utilis&#233;e dans une campagne o&#249; les compagnons d&#39;armes et les suivants peuvent trahir les PJs, mais le MJ doit rappeler aux joueurs qu&#39;il est possible qu&#39;il modifie de temps en temps les actions propos&#233;es par un compagnon d&#39;armes. Pour plus de conseils sur la gestion des compagnons d&#39;armes, consultez la section &lt;a class=&quot;pagelink&quot; href=&quot;Compagnons.html&quot; title=&quot;Les compagnons&quot;&gt;Compagnons&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Le r&#244;le des compagnons d&#39;armes et des suivants&lt;a class=&quot;headeranchor&quot; id=&quot;Le_r&#244;le_des_compagnons_darmes_et_des_suivants_9&quot; href=&quot;#Le_r&#244;le_des_compagnons_darmes_et_des_suivants_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les compagnons d&#39;armes sont traditionnellement des compagnons d&#39;aventure et les suivants sont des personnages d&#39;arri&#232;re-plan qui accomplissent des t&#226;ches pour aider les PJ dans les coulisses. Il y a cependant beaucoup d&#39;autres choses &#224; faire pour ces personnages, comme aider &#224; des activit&#233;s de loisirs ou &#224; la construction d&#39;un royaume. Les options ci-dessous permettent aux compagnons d&#39;&#234;tre plus impliqu&#233;s dans les campagnes, et fournissent &#233;galement des alternatives pour les groupes qui veulent profiter de l&#39;interaction entre les personnages gr&#226;ce aux compagnons d&#39;armes mais qui ne veulent pas plus de personnages en combat.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Contacts.&lt;/b&gt; Lorsque vous utilisez les r&#232;gles de &lt;a class=&quot;pagelink&quot; href=&quot;Contacts.html&quot; title=&quot;Les contacts&quot;&gt;contacts&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt;, une compagnon d&#39;armes ou un suivant peut faire office de contact. Les suivants ont g&#233;n&#233;ralement une valeur de confiance de 3 ou 4, tandis qu&#39;un compagnon d&#39;armes a toujours une valeur de confiance de 5. L&#39;utilisation de compagnons d&#39;armes comme contacts est un bon moyen de les garder en arri&#232;re-plan et loin des projecteurs.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Interm&#232;des.&lt;/b&gt; Le syst&#232;me d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Interm&#232;des.html&quot; title=&quot;Les interm&#232;des&quot;&gt;interm&#232;des&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt; s&#39;inscrivent d&#233;j&#224; avec le don &lt;a class=&quot;pagelink&quot; href=&quot;Prestige.html&quot; title=&quot;Prestige&quot;&gt;Prestige&lt;/a&gt;. Un personnage peut utiliser des suivants comme main-d&#39;œuvre ou les organiser en &#233;quipes, et peut d&#233;signer un compagnon d&#39;armes ou un suivant notable pour servir de gestionnaire de son entreprise.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Casses.&lt;/b&gt; Les suivants peuvent aider &#224; surmonter les obstacles d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Casses.html&quot; title=&quot;Les casses&quot;&gt;casse&lt;/a&gt;. Ils peuvent aider &#224; distraire les gardes, &#224; d&#233;jouer les barri&#232;res, et m&#234;me &#224; braver les p&#233;rils. Les compagnons d&#39;armes peuvent agir comme s&#39;ils &#233;taient des PJs suppl&#233;mentaires pendant le casse, permettant au groupe de faire plus pour atteindre les objectifs du casse.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Influence.&lt;/b&gt; Lorsque vous utilisez le syst&#232;me d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Influence.html&quot; title=&quot;L&amp;#39;influence&quot;&gt;influence&lt;/a&gt;, les compagnons d&#39;armes peuvent potentiellement aider le groupe &#224; gagner de l&#39;influence lors d&#39;un &#233;v&#233;nement social, ce qui permet d&#39;effectuer plus de tests de d&#233;couverte ou d&#39;influence. Un personnage peut &#233;galement offrir les services de ses compagnons d&#39;armes et de ses suivants pour s&#39;attirer les faveurs d&#39;une organisation, et si l&#39;organisation est la source de ces compagnons d&#39;armes ou de ces suivants, le personnage peut gagner des bonus de Prestige suppl&#233;mentaires gr&#226;ce &#224; sa grande influence (voir la section &lt;a class=&quot;pagelink&quot; href=&quot;Prestige-Ui.html#MODIFICATEURS&quot; title=&quot;Le prestige&quot;&gt;Grande renomm&#233;e&lt;/a&gt; page 130).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Royaumes.&lt;/b&gt; Lorsque vous utilisez les r&#232;gles de &lt;a class=&quot;pagelink&quot; href=&quot;Royaumes-Et-Guerre.html&quot; title=&quot;Les royaumes et la guerre&quot;&gt;construction de royaume&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt;, un compagnon d&#39;armes - ou, dans de rares cas, un suivant extr&#234;mement comp&#233;tent - peut servir de responsable gouvernemental.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Combats de masse.&lt;/b&gt; Lorsque vous utilisez les r&#232;gles de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html&quot; title=&quot;Le combat de masse&quot;&gt;combat de masse&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt;, les compagnons d&#39;armes ou les suivants notables peuvent agir en tant que commandants d&#39;arm&#233;es, et un grand groupe de suivants de m&#234;me niveau (comme les compagnons de niveau 1 aux niveaux de Prestige extr&#234;mement &#233;lev&#233;s) peuvent se combiner pour former leur propre arm&#233;e.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#233;putation.&lt;/b&gt; Lorsque vous utilisez le syst&#232;me de &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;putation-Et-Renomm&#233;e.html&quot; title=&quot;R&#233;putation et renomm&#233;e&quot;&gt;r&#233;putation et renomm&#233;e&lt;/a&gt; du &lt;i&gt;Guide de campagne&lt;/i&gt;, un personnage peut demander &#224; ses suivants ou &#224; son compagnon d&#39;armes de r&#233;aliser des actions impressionnantes pour am&#233;liorer sa r&#233;putation. La renomm&#233;e fournit &#233;galement une bonne mesure de la c&#233;l&#233;brit&#233; du personnage pour les bonus de Prestige (voir la section &lt;a class=&quot;pagelink&quot; href=&quot;Prestige-Ui.html#MODIFICATEURS&quot; title=&quot;Le prestige&quot;&gt;Grande renomm&#233;e&lt;/a&gt;, page 130).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Conflits sociaux.&lt;/b&gt; Un groupe engag&#233; dans un &lt;a class=&quot;pagelink&quot; href=&quot;Conflits-Sociaux.html&quot; title=&quot;Les conflits sociaux&quot;&gt;conflit social&lt;/a&gt; peut utiliser des compagnons d&#39;armes ou des suivants comme agents pour tenter d&#39;atteindre des objectifs pendant les &lt;a class=&quot;unknownlink&quot; href=&quot;Conflits-Sociaux,-&#201;v&#232;nements.html#DEFI&quot; title=&quot;Pathfinder-RPG.Conflits sociaux, &#201;v&#232;nements&quot;&gt;d&#233;fis&lt;/a&gt;, ce qui peut augmenter le champ d&#39;action du groupe et lui permettre de participer &#224; plusieurs engagements simultan&#233;ment. Les compagnons d&#39;armes et les suivants sournois, sympathiques ou bien inform&#233;s peuvent aider &#224; d&#233;couvrir les d&#233;fis ou m&#234;me &#224; les relever eux-m&#234;mes.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Duels verbaux.&lt;/b&gt; Un PJ astucieux peut faire pencher la balance en sa faveur en introduisant des suivants dans un auditoire avant un &lt;a class=&quot;pagelink&quot; href=&quot;Duels-Verbaux.html&quot; title=&quot;Les duels verbaux&quot;&gt;duel verbal&lt;/a&gt; afin de gagner des indulgences ou au moins de contrer les pr&#233;jug&#233;s n&#233;gatifs.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Alli&#233;s monstrueux&lt;a class=&quot;headeranchor&quot; id=&quot;Alli&#233;s_monstrueux_10&quot; href=&quot;#Alli&#233;s_monstrueux_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Parfois, se lier d&#39;amiti&#233; avec un monstre au lieu de compter sur la force peut conduire &#224; une exp&#233;rience particuli&#232;rement satisfaisante. La page suivante pr&#233;sente une liste de compagnons d&#39;armes potentiels, avec les sources o&#249; ces monstres apparaissent indiqu&#233;es par les abr&#233;viations en exposant suivantes : Pathfinder-JdR Bestiaire 2 (B2), Pathfinder-JdR Bestiaire 3 (B3), Pathfinder-JdR Bestiaire 4 (B4) ou Pathfinder-JdR Bestiaire 5 (B5). Les monstres dont les sources ne sont pas indiqu&#233;es se trouvent dans le Pathfinder-JdR Bestiaire.&lt;br /&gt;&lt;br /&gt;Le niveau de compagnon d&#39;arme de certains a &#233;t&#233; ajust&#233; par rapport aux publications pr&#233;c&#233;dentes parce que ses capacit&#233;s ont le potentiel d&#39;&#234;tre extr&#234;mement perturbatrices. Utilisez les niveaux de compagnon d&#39;armes pr&#233;sent&#233;s ici au lieu de ceux fournis dans les anciennes publications.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;article_3col&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Compagnons d&#39;armes monstrueux&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Monstre&lt;/td&gt;&lt;td&gt;Niveau de&lt;br/&gt;compagnon d&#39;armes&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adlet.html&quot; title=&quot;Adlet&quot;&gt;Adlet&lt;/a&gt;&lt;sup&gt;B3&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;14&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ahuizotl.html&quot; title=&quot;Ahuizotl&quot;&gt;Ahuizotl&lt;/a&gt;&lt;sup&gt;B3&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aigle-G&#233;ant.html&quot; title=&quot;Aigle, Aigle g&#233;ant&quot;&gt;Aigle g&#233;ant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Apallie.html&quot; title=&quot;Apallie&quot;&gt;Apallie&lt;/a&gt;&lt;sup&gt;B5&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aran&#233;a.html&quot; title=&quot;Aran&#233;a&quot;&gt;Aran&#233;a&lt;/a&gt;&lt;sup&gt;B2&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arbitre.html&quot; title=&quot;In&#233;vitable, Arbitre&quot;&gt;Arbitre&lt;/a&gt;&lt;sup&gt;B2&lt;/sup&gt; (in&#233;vitable)&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archon-Annonciateur.html&quot; title=&quot;Archon, Archon annonciateur&quot;&gt;Archon annonciateur&lt;/a&gt;&lt;sup&gt;B3&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archon-Bouclier.html&quot; title=&quot;Archon, Archon bouclier&quot;&gt;Archon bouclier&lt;/a&gt;&lt;sup&gt;B2&lt;/sup&gt; (archon)&lt;/td&g